input.command:
if [ -z "$GITLAB_TOKEN" ]; then echo "GITLAB_TOKEN not set"; exit 1; fi && curl -s --header "PRIVATE-TOKEN: $GITLAB_TOKEN" "https://mygitlab-dev.ioh.co.id/api/v4/projects/cco%2Fcmo%2Fgroup-digital-coe%2Fdiv-smb-digital-product%2Fide-phoenix/merge_requests/247" | python3 -c "import json, sys; mr = json.load(sys.stdin); print(f'''Title: {mr['title']}
Description: {mr.get('description', 'N/A')[:500]}
Source Branch: {mr['source_branch']}
Target Branch: {mr['target_branch']}
Author: {mr['author']['name']}
Status: {mr['state']}
Web URL: {mr['web_url']}
Diff Refs - base_sha: {mr['diff_refs']['base_sha']}
Diff Refs - head_sha: {mr['diff_refs']['head_sha']}
Diff Refs - start_sha: {mr['diff_refs']['start_sha']}''')"

gh api graphql -f query='
{
  project(fullPath: "cco/cmo/group-digital-coe/div-smb-digital-product/ide-phoenix") {
    mergeRequest(iid: "247") {
      title
      description
      sourceBranch
      targetBranch
      author {
        name
        username
      }
      state
      webUrl
      diffRefs {
        baseSha
        headSha
        startSha
      }
    }
  }
}'
